head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnEditFormat]<br/>Body Column 정보를 사용하여 특정 Column 의 editFormat 속성값을 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 Body Column 의 ID(문자열)를 설정하여 해당 Column 의 editFormat 속성값을 조회할 수 있어야 합니다.",
        "Body Column 의 inputType 이 'text' 가 아니거나 유효하지 않은 ID 이면 false 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 단일 라인 그리드. Body Column ID - txtFmt(text, editFormat=####/##/##) / txtPlain(text, editFormat 미설정) / cal(calendar, 비-text).\n[절차] columnInfo(컬럼 ID) 선택 후 (getColumnEditFormat 실행) 클릭.\n[확인] txtFmt=editFormat 문자열 / txtPlain=미설정 실측값 / cal=false(비-text) / NOT_EXIST=false(유효하지않은 ID) 가 반환영역에 출력됨."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="txtFmt" name="txtFmt" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txtPlain" name="txtPlain" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cal" name="cal" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "txtFmt": "20260101", "txtPlain": "노트북", "cal": "20260201" },
        { "txtFmt": "20260102", "txtPlain": "모니터", "cal": "20260202" },
        { "txtFmt": "20260103", "txtPlain": "키보드", "cal": "20260203" },
        { "txtFmt": "20260104", "txtPlain": "마우스", "cal": "20260204" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (단일 라인 gBody, 3컬럼) - Header inputType 은 text, gBody 가 실제 inputType
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:560px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnEditFormat 테스트 그리드(단일 라인)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol1" value="일자1(text editFormat 설정)"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol2" value="품목(text editFormat 미설정)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="일자2(calendar 비-text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // txtFmt : text, editFormat 설정
    strTarget += '<w2:column width="200" style="" inputType="text" editFormat="####/##/##" editPlaceholderChar="_" id="txtFmt" dataList="txtFmt"></w2:column>';
    // txtPlain : text, editFormat 미설정
    strTarget += '<w2:column width="160" style="" inputType="text" id="txtPlain" dataList="txtPlain"></w2:column>';
    // cal : calendar (비-text)
    strTarget += '<w2:column width="*" style="" inputType="calendar" calendarValueType="yearMonthDate" displayFormat="yyyy/MM/dd" id="cal" dataList="cal"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getColumnEditFormat 조회 (컬럼 ID 문자열 기반)
//  - txtFmt=editFormat 문자열 / txtPlain=미설정 실측값 (ID 로 editFormat 조회)
//  - cal(비-text)=false / NOT_EXIST(유효하지 않은 ID)=false
scwin.btn_getColumnEditFormat_onclick = function () {
    let columnInfo = par_columnInfo.getValue();   // 컬럼 ID 문자열 그대로 전달 (Number 변환 금지)

    let result = target1.getColumnEditFormat(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnEditFormat('" + columnInfo + "') -> 반환값: " + result);
}
